// Code node (n8n) - pega o binary key "IMG" e retorna base64 no json
const output = [];

for (const item of items) {
  const bin = item.binary && (item.binary.IMG || item.binary.data || item.binary.img);

  if (!bin) {
    output.push({ json: { error: 'Nenhum binary key "IMG" encontrado' } });
    continue;
  }

  const raw = bin.data;
  let buffer;

  if (typeof raw === 'string') {
    // se for string (provavelmente já base64), tenta decodificar e re-encodar (garante formato)
    try {
      buffer = Buffer.from(raw, 'base64');
    } catch (e) {
      // se falhar, transforma em Buffer direto
      buffer = Buffer.from(raw);
    }
  } else {
    // se já for Buffer-like
    buffer = Buffer.from(raw);
  }

  const base64 = buffer.toString('base64');

  output.push({
    json: {
      fileName: bin.fileName || null,
      mimeType: bin.mimeType || null,
      base64
    }
  });
}

return output;

